'use strict';
globalThis.ResearchNotes=(()=>{
 const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const $=id=>document.getElementById(id);
 let ppo={ratio:1.5,epsilon:.2,advantage:1};
 function clipped(ratio,advantage,epsilon){return Math.min(ratio*advantage,Math.max(1-epsilon,Math.min(1+epsilon,ratio))*advantage);}
 function table(t){return t?`<div class="table-scroll study-table"><table><thead><tr>${(t.columns||t.headers).map(x=>`<th scope="col">${h(x)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map((x,i)=>i===0?`<th scope="row">${h(x)}</th>`:`<td>${h(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';}
 function sources(items){return items?.length?`<div class="study-sources">${items.map(s=>`<a href="${h(s.url)}" target="_blank" rel="noopener noreferrer">${h(s.title)} ↗<span>${h(s.focus||'')}</span></a>`).join('')}</div>`:'';}
 function overview(k){
  const r=k.readings,rl=k.rl;let out='';
  if(rl)out+=`<section id="guide-section-algorithms" class="study-overview"><div class="visual-kicker">强化学习算法地图</div><h2>${h(rl.title)}</h2><p>${h(rl.intro)}</p><div class="rl-axes">${rl.axes.map(x=>`<article><h3>${h(x.title)}</h3><dl>${x.items.map(item=>`<div><dt>${h(item.label)}</dt><dd>${h(item.text)}</dd></div>`).join('')}</dl><span>${h(x.example)}</span></article>`).join('')}</div><details class="algorithm-comparison"><summary>展开比较 13 类算法 <span>学习方式 · 数据 · 动作 · 核心机制</span></summary>${table(rl.overview)}<p class="study-table-note">${h(rl.tableNote||'')}</p></details><div class="study-shortcuts">${rl.lessons.map(x=>`<a href="#guide?id=${k.id}&section=rl-lesson-${x.id}" data-guide-section="rl-lesson-${x.id}">${h(x.shortTitle||x.title)} <span>↓</span></a>`).join('')}</div></section>`;
  if(r)out+=`<section id="guide-section-paper-map" class="study-overview"><div class="visual-kicker">论文中的方法变化</div><h2>${h(r.title)}</h2><p>${h(r.intro)}</p>${table(r.overview)}<div class="study-shortcuts">${r.lessons.map(x=>`<a href="#guide?id=${k.id}&section=reading-${x.id}" data-guide-section="reading-${x.id}">${h(x.shortTitle||x.title.split('：')[0])} <span>↓</span></a>`).join('')}</div></section>`;
  return out;
 }
 function figure(k,id){const i=k.figures?.findIndex(f=>f.id===id);if(i==null||i<0)return '';const f=k.figures[i];return `<figure class="study-paper-figure"><button type="button" data-paper-zoom="${i}" aria-label="放大论文原图：${h(f.paperTitle)}"><img src="${h(f.src)}" alt="${h(f.alt)}" width="${f.width}" height="${f.height}" loading="lazy"><span>↗ 放大原图</span></button><figcaption>${h(f.paperTitle)} · ${h(f.figure)} · 第 ${f.page} 页</figcaption></figure>${f.reading?.length?`<ol class="study-paper-reading">${f.reading.map(p=>`<li>${h(p)}</li>`).join('')}</ol>`:''}`;}
 function pipeline(steps){return steps?.length?`<ol class="study-pipeline" aria-label="本篇方法数据流">${steps.map((s,i)=>`<li><b><span>${String(i+1).padStart(2,'0')}</span>${h(s.label)}</b><dl><div><dt>输入</dt><dd>${h(s.input)}</dd></div><div><dt>输出</dt><dd>${h(s.output)}</dd></div></dl></li>`).join('')}</ol>`:'';}
 function lesson(k,x,i,kind,eq){return `<details id="guide-section-${kind}-${h(x.id)}" class="study-lesson"${i===0?' open':''}><summary><span class="study-kicker">${h(x.kicker||'机制拆解')}</span><h3>${h(x.title)}</h3><p>${h(x.summary)}</p><span class="study-expand">展开讲解 / 收起</span></summary><div class="study-lesson-body">${x.specs?`<div class="study-specs"><h4>先看清这篇论文的接口</h4>${table(x.specs)}</div>`:''}${pipeline(x.pipeline)}${x.figureId?figure(k,x.figureId):''}${x.sections.map((s,j)=>`<section class="study-part"><span class="study-part-number">${String(j+1).padStart(2,'0')}</span><h4>${h(s.title)}</h4>${s.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}${s.table?table(s.table):''}${s.equations?.length?`<details class="math-disclosure"><summary>公式与符号</summary>${s.equations.map(eq).join('')}</details>`:''}</section>`).join('')}${x.steps?.length?`<ol class="study-steps">${x.steps.map(s=>`<li><h4>${h(s.title)}</h4><p>${h(s.text)}</p></li>`).join('')}</ol>`:''}${x.lab==='ppo'?ppoLab():''}${x.takeaway?`<p class="study-takeaway">${h(x.takeaway)}</p>`:''}${sources(x.sources)}</div></details>`;}
 function body(k,eq){let out='';if(k.rl)out+=`<section id="guide-section-algorithm-notes" class="study-notes"><div class="visual-kicker">从更新规则理解算法</div><h2>沿着一次训练，看清算法怎样工作</h2>${k.rl.lessons.map((x,i)=>lesson(k,x,i,'rl-lesson',eq)).join('')}${k.rl.current?`<article class="rl-current"><h3>${h(k.rl.current.title)}</h3>${k.rl.current.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}${sources(k.rl.current.sources)}</article>`:''}</section>`;
  if(k.readings)out+=`<section id="guide-section-readings" class="study-notes"><div class="visual-kicker">站内论文精读</div><h2>从问题、结构和训练读懂论文</h2><p class="study-section-intro">选择一篇，展开查看它解决的问题、内部计算与训练方式。</p>${k.readings.lessons.map((x,i)=>lesson(k,x,i,'reading',eq)).join('')}</section>`;return out;}
 function ppoLab(){return `<section class="ppo-lab" aria-label="PPO 裁剪目标交互"><h4>移动概率比，观察裁剪在哪里生效</h4><div class="lab-token-buttons"><button type="button" data-ppo-advantage="1" aria-pressed="true">好于预期 · A = +1</button><button type="button" data-ppo-advantage="-1" aria-pressed="false">差于预期 · A = −1</button></div><div class="ppo-controls"><label for="ppo-ratio">新旧概率比 r <output id="ppo-ratio-value">1.50</output></label><input id="ppo-ratio" data-ppo-control="ratio" type="range" min=".25" max="2" step=".01" value="1.5"><label for="ppo-epsilon">裁剪宽度 ε <output id="ppo-epsilon-value">0.20</output></label><input id="ppo-epsilon" data-ppo-control="epsilon" type="range" min=".05" max=".4" step=".01" value=".2"></div><div id="ppo-plot" aria-live="polite"></div></section>`;}
 function drawPpo(){if(!$('ppo-plot'))return;const {ratio:r,epsilon:e,advantage:a}=ppo;const X=x=>65+(x-.2)/1.85*600,Y=y=>a>0?270-y*110:40-y*110;const ys=a>0?[0,.5,1,1.5,2]:[0,-.5,-1,-1.5,-2];const points=Array.from({length:101},(_,i)=>{const v=.2+i*1.85/100;return `${X(v)},${Y(clipped(v,a,e))}`;}).join(' ');const value=clipped(r,a,e),flat=a>0?r>1+e:r<1-e;
  $('ppo-plot').innerHTML=`<svg viewBox="0 0 720 335" role="img" aria-label="PPO 单样本裁剪目标曲线"><rect x="${X(1-e)}" y="25" width="${X(1+e)-X(1-e)}" height="255" fill="#edf2e5"/><path d="M65 25V280H680" fill="none" stroke="#a9b9a0"/>${ys.map(v=>`<text x="48" y="${Y(v)+5}" text-anchor="end" class="svg-tick">${v}</text>`).join('')}<path d="M${X(.2)} ${Y(.2*a)}L${X(2.05)} ${Y(2.05*a)}" fill="none" stroke="#b88042" stroke-width="2" stroke-dasharray="6 4"/><polyline points="${points}" fill="none" stroke="#355c42" stroke-width="4"/>${[1-e,1,1+e].map(v=>`<path d="M${X(v)} 25V280" stroke="#bccbb3" stroke-dasharray="3 4"/><text x="${X(v)}" y="${v===1?323:301}" text-anchor="middle" class="svg-tick">${v.toFixed(2)}</text>`).join('')}<circle cx="${X(r)}" cy="${Y(value)}" r="7" fill="#47768a"/><text x="70" y="18" class="svg-label">要最大化的策略目标</text><text x="675" y="326" text-anchor="end" class="svg-label">概率比 r →</text></svg><div class="ppo-legend"><span>━━ 绿色：PPO 取较小项</span><span>┄ 橙色：未裁剪的 rA</span></div><div class="lab-stats"><span>原始项 <b>${(r*a).toFixed(2)}</b></span><span>裁剪候选 <b>${(Math.max(1-e,Math.min(1+e,r))*a).toFixed(2)}</b></span><span>实际目标 <b>${value.toFixed(2)}</b></span></div><p class="ppo-reading">${a>0?`优势为正，模型要提高这个动作的概率。r 超过 ${(1+e).toFixed(2)} 后，曲线变平，该样本不再鼓励继续增大概率。`:`优势为负，模型要降低这个动作的概率。r 低于 ${(1-e).toFixed(2)} 后，曲线变平，该样本不再鼓励继续减小概率。`}</p><p class="ppo-reading">当前点${flat?'在平坦段':'在有斜率的区间'}。固定旧概率为 0.20，新概率为 ${(r*.2).toFixed(3)}。裁剪调整目标函数的梯度；共享参数更新后，概率比仍可能越过参考区间，因此训练还会监测 KL 与裁剪比例。</p>`;
 }
 function mount(){ppo={ratio:1.5,epsilon:.2,advantage:1};drawPpo();}
 document.addEventListener('click',ev=>{const t=ev.target.closest('[data-ppo-advantage]');if(t){ppo.advantage=Number(t.dataset.ppoAdvantage);document.querySelectorAll('[data-ppo-advantage]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.ppoAdvantage)===ppo.advantage));drawPpo();}});
 document.addEventListener('input',ev=>{const control=ev.target.dataset.ppoControl;if(control==='ratio'||control==='epsilon'){ppo[control]=Number(ev.target.value);$('ppo-'+control+'-value').textContent=ppo[control].toFixed(2);drawPpo();}});
 function search(k){return JSON.stringify([k.readings||{},k.rl||{}]);}
 return {overview,body,mount,search,clipped};
})();
